/* Read-only field explanations. Saving and the existing record semantics stay in editTerritory. */
(function(){'use strict';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</span>`,P=(en,ko)=>`<p>${L(en,ko)}</p>`,bindings=new WeakMap(),R=()=>window.RULES_DATA||{};
const entries={
 name:{title:['Territory name & Reset','영토 이름·초기화'],what:['The display name for this territory record. Reset restores only the stored original name.','이 영토 기록의 표시 이름입니다. 초기화는 저장된 원래 이름만 되돌립니다.'],use:['Use a local nickname to distinguish repeated territories. The name is limited to 50 characters. Renaming does not replace the linked territory rule, income, owner or description.','같은 영토가 여러 개일 때 구역별 별칭을 붙이는 데 씁니다. 최대 50자이며, 이름을 바꿔도 연결된 영토 룰·수입·소유자·설명이 다른 영토의 것으로 바뀌지는 않습니다.'],example:['Example: rename Synth Still to East-side Still. Reset returns the original name stored on that record; it does not undo the other fields in this form.','예: Synth Still을 동쪽 증류소로 바꿔 구분할 수 있습니다. 초기화를 누르면 이 기록에 처음 저장한 이름으로 돌아갑니다. 이 창의 다른 입력값을 취소하는 버튼은 아닙니다.']},
 playingCard:{title:['Playing card reference','플레잉 카드·참고 번호'],what:['An optional card label used to identify this territory in your group’s records. “None” is allowed.','모임에서 이 영토를 구분하기 위해 붙이는 선택형 카드 라벨입니다. 없음으로 두어도 됩니다.'],use:['Choose a suit/rank or a custom reference when your campaign uses physical cards or reference codes. This field does not roll or generate a territory, change its effects, or assign an owner.','실물 카드나 참고 코드를 쓰는 캠페인에서 무늬·숫자 또는 사용자 정의 라벨을 붙일 때 씁니다. 이 필드는 영토를 무작위로 뽑거나 효과·소유자를 바꾸지 않습니다.'],example:['Example: label a Synth Still 6♠ and refer to that record as 6♠ on the table. Its rules remain Synth Still. The N26 D66 territory draw is a separate feature, not a requirement to select a playing card here.','예: 신스 스틸에 6♠를 붙여 테이블에서 6♠ 영토라고 부를 수 있습니다. 룰은 그대로 신스 스틸입니다. N26의 D66 영토 무작위 추출은 별도 기능이며, 여기서 카드를 골라야 추출되는 것이 아닙니다.']},
 customPlayingCard:{title:['Custom territory reference','사용자 정의 참고 카드'],what:['A manually written reference used when Playing card is set to Custom.','플레잉 카드에서 사용자 정의를 골랐을 때 쓰는 직접 입력 라벨입니다.'],use:['Use your group’s own labels rather than a standard playing-card value. It is a reference only and does not create a new official card or rule.','표준 카드 대신 모임의 구역 이름·관리 코드를 적을 때 씁니다. 참고 라벨이며 새로운 공식 카드나 룰을 만들지는 않습니다.'],example:['Example: enter Sector C-04. Selecting a normal card or None again uses that selection instead of this custom text.','예: C-04 구역이라고 적을 수 있습니다. 다시 일반 카드나 없음을 고르면 그 선택값이 사용됩니다.']},
 credits:{title:['Territory income (credits)','영토 수입·크레딧'],what:['The recorded income amount for this territory. It is not the purchase price or the gang’s current cash balance.','이 영토에 기록한 수입 금액입니다. 영토 구매 가격이나 갱의 현재 현금 잔액이 아닙니다.'],use:['Saving an amount does not pay the gang immediately. Resolve the applicable income step and record the actual credits separately. A numeric edit does not rewrite the description below.','수치를 저장한다고 갱에게 즉시 지급되지는 않습니다. 해당 수입 수집 단계를 처리한 뒤 실제 크레딧을 따로 기록하세요. 숫자를 바꿔도 아래 설명문은 자동으로 고쳐지지 않습니다.'],example:['Example: Synth Still’s verified N26 entry lists 20 credits at Collect Income. An explicit 0 records zero income. A blank field clears the income record to “unrecorded”; it does not automatically restore 20.','예: 신스 스틸의 확인된 N26 원문은 수입 수집 때 20크레딧입니다. 0을 입력하면 수입 0으로 기록합니다. 빈칸은 수입 미기록으로 지우는 것이며 자동으로 20으로 복구하는 기능이 아닙니다.']},
 ruined:{title:['Ruined status','폐허 상태'],what:['This marks the territory as ruined or damaged in the record. It does not delete the territory. The former Korean label “폐기” was misleading.','이 영토가 훼손·폐허 상태임을 기록하는 표시입니다. 영토를 삭제하는 기능이 아닙니다. 기존의 폐기 표기는 뜻이 불분명해 폐허 상태로 바꿨습니다.'],use:['Use it when your scenario, campaign pack or agreed ruling needs a ruined-state record. The current app adds a Ruined badge and visual marking, including print. It does not automatically set income to 0, remove ownership, remove the territory from the stake list or cancel its benefits.','시나리오·캠페인 팩·합의한 판정에 따라 훼손 상태를 기록할 때 씁니다. 현재 앱은 폐허 배지와 시각적 표시를 붙이고 출력물에도 표시합니다. 수입 0·소유권 해제·내기 후보 제외·혜택 취소를 자동 처리하지는 않습니다.'],example:['Example: with Synth Still income 20, checking Ruined alone leaves the recorded income at 20. If your applicable ruling suspends income, record that separately and state the ruling in Description; this checkbox does not establish a universal N26 ruin penalty.','예: 수입 20인 신스 스틸에 폐허만 체크하면 기록 수입은 여전히 20입니다. 적용 중인 판정이 수입 중단을 정했다면 별도로 기록하고 설명에 근거를 적으세요. 이 체크박스가 N26 공통 폐허 페널티를 정하는 것은 아닙니다.']},
 defaultGangTerritory:{title:['Starting home territory / exclude from stakes','기본 거점 영토·내기 제외'],what:['A record flag used for a gang’s protected home territory. It is different from an ordinary territory that happened to be drawn at campaign setup.','갱의 기본 거점 영토를 구분하는 기록 설정입니다. 캠페인 시작 때 우연히 추출한 일반 영토와는 다릅니다.'],use:['In this app, checked territories are excluded from battle-stake candidates and follow the main page’s List Default Territories display filter. The flag does not grant Settlement rules, add a new territory, change the owner or lock manual owner/edit/delete actions.','앱에서는 체크한 영토가 전투 내기 후보에서 제외되고, 메인 화면의 기본 영토 목록 표시 필터와 연결됩니다. 세틀먼트 룰을 부여하거나 영토를 추가하거나 소유자를 바꾸지 않으며, 관리자의 소유자 수정·해제·삭제를 잠그는 기능도 아닙니다.'],example:['Example: marking Synth Still as a home territory removes it from this app’s stake candidates; it does not turn its 20-credit income or Toxin-related battle effect into Settlement’s rules. Use such an override only to record your campaign’s actual ruling.','예: 신스 스틸에 기본 거점을 체크하면 앱의 내기 후보에서 빠집니다. 하지만 수입 20이나 톡신 관련 전장 효과가 세틀먼트의 룰로 바뀌지는 않습니다. 이처럼 따로 지정할 때는 실제 캠페인의 판정에 맞춰 기록하세요.']},
 description:{title:['Territory description & custom override','영토 설명·사용자 수정'],what:['The text players read when opening this territory’s explanation. Up to 2,000 characters.','이 영토의 설명을 열었을 때 플레이어가 읽는 내용입니다. 최대 2,000자입니다.'],use:['Use it to keep the benefit, timing and agreed exceptions together. Changing the text stores a custom override; it does not change the official catalogue. Clearing the text deliberately leaves this record blank. It does not automatically restore the official wording.','혜택·적용 시점·합의한 예외를 함께 적을 때 씁니다. 내용을 바꾸면 이 기록의 사용자 설명으로 저장되며 공식 목록은 바뀌지 않습니다. 설명을 지우면 이 기록의 설명을 빈칸으로 두는 것이며 원문이 자동 복구되지는 않습니다.'],example:['Example: note a campaign-specific suspension and its effective cycle here. Text alone does not change the income amount, checkbox values, owner or weapon AP. Open the original rule below to compare the source with your edited record.','예: 캠페인 합의로 혜택을 중단했다면 적용 사이클과 판정을 적을 수 있습니다. 글만 바꿔서는 수입 수치·체크 상태·소유자·무기 AP가 바뀌지 않습니다. 아래 원문 룰을 열어 수정한 기록과 비교하세요.']}
};
function fold(en,ko,body,key){return `<details class="teh-section" data-territory-help-section="${key}"><summary>${L(en,ko)}</summary><div>${body}</div></details>`;}
function source(t,c){const r=window.MMCampaignData?.territoryRule(t,c);return r?.source_verified&&String(r.edition_slug||r.edition).toLowerCase()===String(c?.edition).toLowerCase()?r:null;}
function open(key,{item,campaign:c,form,activator}={}){
 const entry=entries[key];if(!entry||!item||!c)return false;const rule=source(item,c),n26=window.MMCampaignFieldGuide?.supported(c),rd=rule?.rule_data||{},settlement=(R().territories||[]).find(r=>r.id==='official-003-territory-settlement'&&r.source_verified),protectedByRule=rd.can_be_staked===false||rd.can_be_lost===false||rd.cannot_lose===true;
 const current=form?.elements?.[key],draft=current?current.type==='checkbox'?L(current.checked?'Checked in this unsaved form':'Unchecked in this unsaved form',current.checked?'현재 편집에서 체크됨':'현재 편집에서 체크 안 됨'):E(current.value||'—'):'';
 let example=entry.example;if(!n26&&['playingCard','credits','defaultGangTerritory'].includes(key))example=key==='defaultGangTerritory'?['Example: marking an ordinary territory as a home territory excludes it from this app’s stake candidates, but grants no new rules. Check your campaign’s ruling.','예: 일반 영토를 기본 거점으로 체크하면 앱 내기 후보에서는 제외되지만 새 룰이 생기지는 않습니다. 실제 캠페인 판정을 확인하세요.']:key==='credits'?['Example: 0 explicitly records zero income; blank records no amount. Consult the selected edition and territory for when and how much to collect.','예: 0은 수입 0이고 빈칸은 금액 미기록입니다. 수입 시점과 금액은 해당 판본·영토의 규칙을 확인하세요.']:['Example: 6♠ is a reference label for a territory record; it does not change the linked territory rule.','예: 6♠는 영토 기록의 참고 라벨이며 연결된 영토 룰을 바꾸지 않습니다.'];
 const home=n26&&key==='defaultGangTerritory'&&settlement?P('Verified N26 example: Settlement is each gang’s starting hideout and cannot be lost or staked. At Collect Income, take 15 credits or instead recruit one Ganger-subtype Fighter at a 25-credit discount (minimum zero). A normal randomly drawn territory is not automatically a home territory.','N26의 확인된 예: 세틀먼트는 각 갱의 시작 거점이며 잃거나 전투의 내기로 걸 수 없습니다. 수입 수집 때 15크레딧을 받거나, 그 대신 갱어 서브타입 파이터 1명을 정상 비용보다 25크레딧 싸게 모집합니다(최소 0). 일반 무작위 영토가 자동으로 기본 거점이 되는 것은 아닙니다.')+(protectedByRule?P('This territory’s verified source already forbids stakes. Clearing the home-territory flag does not override that source restriction.','이 영토의 확인된 원문 자체가 내기를 금지합니다. 기본 거점 체크를 해제해도 그 원문 제한이 풀리지 않습니다.'):''):'';
 const body=`<div class="teh-guide" data-territory-editor-guide="${E(key)}"><div class="teh-badge">${L('Field explanation · app record','항목 설명 · 앱 기록')}</div>${P(...entry.what)}${draft?`<p class="teh-draft">${L('Current unsaved input','현재 편집 중인 값')}: ${draft}</p>`:''}${fold('When to use / what changes','언제 쓰나·무엇이 바뀌나',P(...entry.use),'use')}${fold('Example','상황 예시',P(...example)+home,'example')}${key==='ruined'?fold('Ruined, release owner and delete are different actions','폐허 표시·소유자 해제·삭제의 차이',`<dl class="teh-actions"><div><dt>${L('Ruined','폐허 표시')}</dt><dd>${L('Keep the record and owner; add a status marker.','기록과 소유자를 유지하고 상태만 표시합니다.')}</dd></div><div><dt>${L('Release owner','소유자 해제')}</dt><dd>${L('Keep the territory record but clear its owning gang.','영토 기록은 유지하고 통제 갱을 해제합니다.')}</dd></div><div><dt>${L('Delete territory','영토 삭제')}</dt><dd>${L('Remove the territory record and clear its map-object territory links.','영토 기록을 제거하고 지도 개체의 영토 연결을 해제합니다.')}</dd></div></dl>`,'actions'):''}${fold('Save and rule references','저장·원문 확인',P('This guide does not edit or save any field. Changes take effect only when you submit Update Territory; Cancel keeps the previously saved record.','이 설명은 입력값을 수정하거나 저장하지 않습니다. 영토 업데이트를 눌러야 편집 내용이 반영되며, 취소하면 이전 저장 기록을 유지합니다.')+(rule?`<button type="button" class="btn small" data-territory-help-source="${E(rule.id)}" data-territory-help-edition="${E(c.edition)}">${L('Open this territory’s verified original rule','이 영토의 확인된 원문 룰 보기')}</button>`:P('No verified linked original is available for this record. Use your campaign pack and authored description.','이 기록에 연결된 확인 원문이 없습니다. 캠페인 팩과 직접 작성한 설명을 확인하세요.'))+(home?`<button type="button" class="btn small" data-territory-help-source="${E(settlement.id)}" data-territory-help-edition="n26">${L('Settlement original rule','세틀먼트 원문 룰')}</button>`:''),'save')}</div>`;
 return window.MMRuleReference?.openContext(entry.title[0],body,{nameKo:entry.title[1],activator,nested:!!document.querySelector('.mmrr-overlay')})||false;
}
function decorate(item,c){
 const form=document.querySelector('#modal-form');if(!form||form.dataset.territoryEditorReady)return;form.dataset.territoryEditorReady='true';
 for(const key of Object.keys(entries)){const field=form.elements[key];if(!field||!field.closest)continue;const host=field.closest('label,.mm-combo-label');if(!host)continue;const wrap=document.createElement('div');wrap.className='teh-field wide';host.before(wrap);wrap.append(host);if(['ruined','defaultGangTerritory'].includes(key)){wrap.classList.add('teh-check');host.replaceChildren(field);const span=document.createElement('span');span.innerHTML=key==='ruined'?L('Ruined status','폐허 상태'):L('Home territory (exclude from stakes)','기본 거점(내기 제외)');host.append(span);}else if(key==='credits'){for(const node of [...host.childNodes])if(node.nodeType===3&&node.textContent.trim()){const span=document.createElement('span');span.innerHTML=L('Income (credits)','수입(크레딧)');node.replaceWith(span);break;}}
 const button=document.createElement('button');button.type='button';button.className='teh-help';button.dataset.territoryEditorHelp=key;button.setAttribute('aria-haspopup','dialog');button.dataset.i18nEnAriaLabel=entries[key].title[0]+' — View explanation';button.dataset.i18nKoAriaLabel=entries[key].title[1]+' 설명 보기';button.setAttribute('aria-label',button.dataset.i18nEnAriaLabel);button.innerHTML='<span aria-hidden="true">ⓘ</span>';bindings.set(button,{item:JSON.parse(JSON.stringify(item)),campaign:{edition:c.edition,campaignTypeId:c.campaignTypeId,campaignType:c.campaignType},form});wrap.append(button);
 if(key==='ruined'||key==='defaultGangTerritory'){const note=document.createElement('p');note.className='teh-hint';note.innerHTML=key==='ruined'?L('Status marker; income and ownership are not changed automatically.','상태 표시이며 수입·소유권은 자동 변경하지 않습니다.'):L('Home-territory flag; excluded from battle-stake candidates.','기본 거점 표시이며 전투 내기 후보에서 제외합니다.');wrap.append(note);}
 }
 window.UKI18n?.refresh(form);
}
window.addEventListener('click',e=>{const b=e.target.closest?.('[data-territory-editor-help],[data-territory-help-source]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.dataset.territoryHelpSource)return window.MMRuleReference?.open('territories',b.dataset.territoryHelpSource,{edition:b.dataset.territoryHelpEdition,activator:b,nested:true});const bound=bindings.get(b);if(bound)open(b.dataset.territoryEditorHelp,{...bound,activator:b});},true);
window.MMTerritoryEditorHelp={decorate,open};
})();
